import pandas as pd, collections
idx = {}
import csv
with open('/practice/index.tsv') as f:
    rd = csv.DictReader(f, delimiter='\t')
    for row in rd:
        idx[row['id']] = row
for r in sel_rows:
    r['level'] = idx.get(r['qid'],{}).get('level')
cnt = collections.Counter(r['level'] for r in sel_rows)
acc = collections.defaultdict(list); cut = collections.defaultdict(list); nb= collections.defaultdict(list)
for r in sel_rows:
    acc[r['level']].append(r['correct']); cut[r['level']].append(r['finish']=='length'); nb[r['level']].append(not r['extracted'])
for lv in sorted(cnt, key=lambda x: (x is None, x)):
    print(lv, 'n', len(acc[lv]), 'acc', round(sum(acc[lv])/len(acc[lv]),3), 'cut', round(sum(cut[lv])/len(cut[lv]),3), 'nobox', round(sum(nb[lv])/len(nb[lv]),3))

